package local.my0511.lite;
import java.time.*;
import java.util.*;
public final class RulesTest {
 static int count;static void ok(boolean b,String why){if(!b)throw new AssertionError(why);count++;}static void rejects(Runnable f){try{f.run();throw new AssertionError("expected rejection");}catch(IllegalArgumentException expected){count++;}}
 static long at(String s){return LocalDateTime.parse(s).atZone(PublishRules.ZONE).toInstant().toEpochMilli();}
 public static void main(String[] args){List<Task> rows=BulkPaste.parse("标题甲\n第一段===内部\n===\n标题乙\n第二段",false,"");ok(rows.size()==2,"only own-line delimiter");ok(rows.get(0).message.equals("第一段===内部"),"inline preserved");ok(rows.get(1).state==Task.State.DRAFT,"never auto approved");ok(BulkPaste.parse("\r\n===\r\n一\r\n===\r\n二",true,"123").size()==2,"reply CRLF and empty edge");rejects(()->BulkPaste.parse("只写标题",false,""));rejects(()->BulkPaste.parse("a\nb\n===\na\nb",false,""));rejects(()->BulkPaste.parse("x",true,"https://evil.test/thread-123-1-1.html"));StringBuilder many=new StringBuilder();for(int i=0;i<101;i++)many.append("===\n标题").append(i).append("\n正文\n");rejects(()->BulkPaste.parse(many.toString(),false,""));
 Task t=rows.get(0);t.accountId="1";Task other=BulkPaste.parse("标题甲\n第一段===内部",false,"").get(0);other.accountId="2";ok(!t.fingerprint().equals(other.fingerprint()),"per-account dedup");
 PublishRules r=new PublishRules();long now=at("2026-11-05T10:00");ok(r.active(now),"active weekday");ok(!r.active(at("2026-11-05T22:30")),"end exclusive");r.start=1320;r.end=120;ok(r.active(at("2026-11-05T23:00"))&&r.active(at("2026-11-06T01:00")),"overnight window");ok(!r.active(now),"overnight excluded midday");r.start=r.end=0;r.quietDays=2;ok(!r.active(at("2026-11-07T10:00"))&&!r.active(at("2026-11-08T10:00")),"quiet weekend");r.quietDays=0;r.start=540;r.end=1350;
 ok(r.blocked(t,"2",now,0,0,0).contains("账户"),"wrong account");ok(r.blocked(t,"1",now,now-60000,0,0).contains("间隔"),"min gap");ok(r.blocked(t,"1",now,0,3,0).contains("每日"),"daily cap");t.reply=true;ok(r.blocked(t,"1",now,0,0,2).contains("该帖"),"per thread cap");t.latest=now-1;ok(r.blocked(t,"1",now,0,0,0).contains("最晚"),"expired");t.latest=0;t.at=now+1000;ok(r.blocked(t,"1",now,0,0,0).contains("计划"),"not before earliest");t.at=0;ok(r.blocked(t,"1",now,0,0,0).isEmpty(),"eligible");r.meanMinutes=30;long plan=r.planned(t,now,now);ok(plan>=now+10*60000&&plan<=now+50*60000,"jitter bounded above minimum");t.plannedAt=plan;ok(r.planned(t,now+99999999,now)==plan,"plan stable when resumed");ok(PublishRules.day(at("2026-11-06T00:00")).equals("2026-11-06"),"Beijing day");rejects(()->PublishRules.minute("24:00"));rejects(()->PublishRules.minute("09:60"));ok(PublishRules.minute("09:05")==545,"parse clock");t.plannedAt=0;t.at=now+120000;t.latest=0;ok(r.planned(t,now,0)==t.at,"specified time has no added random delay");t.latest=t.at+1000;ok(r.planned(t,now,0)<=t.latest,"random plan stays inside available range");t.at=t.latest=0;t.holdUntil=now+900000;ok(r.blocked(t,"1",now,0,0,0).contains("暂缓"),"self-reply hold enforced");r.meanMinutes=1;rejects(r::validate);
 System.out.println("PASS "+count+" G bulk-paste/account/schedule boundary checks");}
}
